# Provenance: 3rd analysis of 2026-11-15 (section 10 of ACHADOS). Read-only. POST HOC.
# Held-out set of the paper (39 scenarios, submitted method): per guard regime, and the difference to VARLiNGAM with and
# without Causal Chambers. Input: res_b2_portao.csv (generated by b2_gate.py).
import os
import re
import sys

import numpy as np
import pandas as pd
from scipy.stats import wilcoxon

F2 = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))  # repository root
txt = open(os.path.join(F2, "Results", "Run_20261011_132346", "evaluation_scope.txt"), encoding="utf-8", errors="replace").read()
ho = set(re.findall(r"^\s*((?:real|benchmark)_\S+)\s*:", txt, flags=re.M))
D = pd.read_csv(sys.argv[1])
A = D[D.conj == "art90"]
H = A[A.cenario.isin(ho) | A.cenario.str.contains("causal_chamber|rcaeval")].copy()
BL = ["pcmci_tigramite_tau10", "pcmciplus_tau10", "dynotears_tau10", "cuts_plus_tau10", "varlingam_tau10"]
pd.set_option("display.width", 250)
print("held-out:", len(H), "scenarios | official mean F1:", round(H.f1_oficial.mean(), 4), "| below the floor:", int((H.atual_f1 < H.piso).sum()))
for b in BL:
    d = (H.atual_f1 - H[b]).dropna()
    print("  current - %-22s n=%d diff %+.3f (%d/%d) p=%.3g" % (b, len(d), d.mean(), (d > 0).sum(), (d < 0).sum(), wilcoxon(d).pvalue))
H["grupo"] = np.where(H.regime != "incoherent", H.regime, "incoh/" + H.fallback.astype(str))
H["lift"] = H.atual_prec / H.taxa_base
H["sob"] = H.atual_f1 < H.piso
print(H.groupby("grupo").agg(cen=("sob", "size"), f1=("atual_f1", "mean"), piso=("piso", "mean"), sob_piso=("sob", "sum"),
                             lift_mediana=("lift", "median"), mcc=("atual_mcc", "mean"), cuts=("cuts_plus_tau10", "mean"),
                             varlingam=("varlingam_tau10", "mean")).round(3).to_string())
H["cc"] = H.cenario.str.contains("causal_chamber")
for name, S in [("Causal Chambers", H[H.cc]), ("held-out without Causal Chambers", H[~H.cc])]:
    d = (S.atual_f1 - S.varlingam_tau10).dropna()
    print("%s: n=%d current %.3f VARLiNGAM %.3f diff %+.3f (%d/%d) p=%.3g" % (
        name, len(d), S.atual_f1[d.index].mean(), S.varlingam_tau10[d.index].mean(), d.mean(), (d > 0).sum(), (d < 0).sum(),
        wilcoxon(d).pvalue))
H["fam"] = H.cenario.str.replace("benchmark_|real_", "", regex=True).str.split("_").str[0]
print(H.groupby("fam").agg(cen=("sob", "size"), atual=("atual_f1", "mean"), varlingam=("varlingam_tau10", "mean"),
                           cuts=("cuts_plus_tau10", "mean"), piso=("piso", "mean"), lift=("lift", "median")).round(3).to_string())
